#!/bin/bash
# Paper-level evaluation on the public (train) instances.
#
# Runs every compiler registered in outputs/compilers/*.json on the instances
# generated by eval/train/ and writes scoring/scores.json.  Self-contained:
# uses only eval/ (never method/); any method that registers a compiler
# command is scored the same way.
#
# Usage: bash scripts/evaluate.sh

set -e
cd /home/user
mkdir -p scoring
python3 eval/train/evaluate.py --output scoring/scores.json
